//! Generated files on disk: written only where their contents change, and deleted
//! where a stack no longer produces them.

use std::fs;
use std::io::{BufRead, BufReader};
use std::path::{Path, PathBuf};

const HEADER_START: &str = "DO NOT EDIT. Generated by tfgen";

/// The header a generated file carries, naming what it is generated from.
pub fn header_comment(sources: &[String]) -> String {
    format!("{HEADER_START} from {}.", factored_paths(sources))
}

/// Slash paths with the directory they share written once: `a/{b/c.yml, c.yml}`.
fn factored_paths(paths: &[String]) -> String {
    let [first, rest @ ..] = paths else {
        return String::new();
    };
    if rest.is_empty() {
        return first.clone();
    }
    let directories = |path: &str| -> Vec<String> {
        let mut parts: Vec<String> = path.split('/').map(str::to_owned).collect();
        parts.pop();
        parts
    };
    let mut shared = directories(first);
    for path in rest {
        let other = directories(path);
        let length = shared
            .iter()
            .zip(&other)
            .take_while(|(first, second)| first == second)
            .count();
        shared.truncate(length);
    }
    let prefix_length: usize = shared.iter().map(|part| part.len() + 1).sum();
    let tails: Vec<&str> = paths.iter().map(|path| &path[prefix_length..]).collect();
    let listed = format!("{{{}}}", tails.join(", "));
    if shared.is_empty() {
        listed
    } else {
        format!("{}/{listed}", shared.join("/"))
    }
}

/// How a write changed a file on disk.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum FileChange {
    Created,
    Changed,
    Deleted,
}

/// What one stack's write changed on disk: each file it touched, by path.
#[derive(Default)]
pub struct DiskChanges {
    pub files: Vec<(PathBuf, FileChange)>,
}

/// Writes `files` where they change, then deletes every file of `directory` that
/// carries tfgen's header and is not among them.
pub fn write_stack_files(
    directory: &Path,
    files: &[(PathBuf, String)],
) -> Result<DiskChanges, String> {
    let mut changes = DiskChanges::default();
    for (path, contents) in files {
        let current = fs::read_to_string(path).ok();
        if current.as_deref() != Some(contents.as_str()) {
            fs::write(path, contents)
                .map_err(|error| format!("writing {}: {error}", path.display()))?;
            let change = match current {
                Some(_) => FileChange::Changed,
                None => FileChange::Created,
            };
            changes.files.push((path.clone(), change));
        }
    }
    let listed = fs::read_dir(directory)
        .map_err(|error| format!("reading {}: {error}", directory.display()))?;
    let mut stale = Vec::new();
    for entry in listed.flatten() {
        let path = entry.path();
        if path.is_file()
            && !files.iter().any(|(written, _)| *written == path)
            && carries_header(&path)
        {
            stale.push(path);
        }
    }
    stale.sort();
    for path in stale {
        fs::remove_file(&path).map_err(|error| format!("deleting {}: {error}", path.display()))?;
        changes.files.push((path, FileChange::Deleted));
    }
    changes
        .files
        .sort_by(|first, second| first.0.cmp(&second.0));
    Ok(changes)
}

fn carries_header(path: &Path) -> bool {
    let Ok(file) = fs::File::open(path) else {
        return false;
    };
    let mut first_line = String::new();
    if BufReader::new(file).read_line(&mut first_line).is_err() {
        return false;
    }
    first_line
        .strip_prefix('#')
        .is_some_and(|comment| comment.trim_start().starts_with(HEADER_START))
}

#[cfg(test)]
mod tests {
    use super::*;

    struct ScratchDirectory(PathBuf);

    impl ScratchDirectory {
        fn new(name: &str) -> Self {
            let path = std::env::temp_dir().join(format!("tfgen-{name}-{}", std::process::id()));
            let _ = fs::remove_dir_all(&path);
            fs::create_dir_all(&path).unwrap();
            Self(path)
        }
    }

    impl Drop for ScratchDirectory {
        fn drop(&mut self) {
            let _ = fs::remove_dir_all(&self.0);
        }
    }

    #[test]
    fn a_header_writes_the_directory_its_sources_share_once() {
        let sources = |paths: &[&str]| -> Vec<String> {
            paths.iter().map(|path| (*path).to_owned()).collect()
        };
        assert_eq!(
            header_comment(&sources(&[
                "rds/mock/dev/resources.yml",
                "rds/mock/resources.yml"
            ])),
            "DO NOT EDIT. Generated by tfgen from rds/mock/{dev/resources.yml, resources.yml}."
        );
        assert_eq!(
            header_comment(&sources(&["mock/build/resources.yml"])),
            "DO NOT EDIT. Generated by tfgen from mock/build/resources.yml."
        );
        assert_eq!(
            factored_paths(&sources(&["a.yml", "b/c.yml"])),
            "{a.yml, b/c.yml}"
        );
    }

    #[test]
    fn only_changed_files_are_written_and_only_tfgen_files_are_deleted() {
        let scratch = ScratchDirectory::new("generated-files");
        let kept = scratch.0.join("main.tf");
        let stale = scratch.0.join("old.tf");
        let hand_written = scratch.0.join("migration.tf");
        let header = format!("# {}\n", header_comment(&["mock.yml".into()]));
        fs::write(&kept, format!("{header}a = 1\n")).unwrap();
        fs::write(&stale, format!("{header}b = 1\n")).unwrap();
        fs::write(&hand_written, "c = 1\n").unwrap();
        let created = scratch.0.join("providers.tf");
        let files = vec![
            (kept.clone(), format!("{header}a = 1\n")),
            (created.clone(), format!("{header}c = 1\n")),
        ];
        let changes = write_stack_files(&scratch.0, &files).unwrap();
        assert_eq!(
            changes.files,
            [
                (stale.clone(), FileChange::Deleted),
                (created.clone(), FileChange::Created)
            ]
        );
        assert!(hand_written.exists() && !stale.exists());
        let files = vec![
            (kept.clone(), format!("{header}a = 2\n")),
            (created, format!("{header}c = 1\n")),
        ];
        let changes = write_stack_files(&scratch.0, &files).unwrap();
        assert_eq!(changes.files, [(kept, FileChange::Changed)]);
    }
}
